  function logoBox(logo) { const m = String(logo || '').match(/([a-z0-9_-]+)\.(webp|png|svg|jpg)/i); return (m && LOGO_BOX[m[1].toLowerCase()]) || [0, 0, 1, 1, 1, .5]; }
